import React, { useId } from "react";

interface VerifiedBadgeProps extends React.SVGProps<SVGSVGElement> {
  size?: number | string;
  badgeColor?: string;
  checkColor?: string;
  enableGlint?: boolean;
  glintDuration?: string;
  className?: string;
}

export const VerifiedBadge: React.FC<VerifiedBadgeProps> = ({
  size = 24,
  badgeColor = "#1877F2", // Vibrant Blue matching the reference image
  checkColor = "#323436", // Dark charcoal cutout tone
  enableGlint = true,
  glintDuration = "3.5s",
  className = "",
  ...props
}) => {
  const uniqueId = useId();
  const clipPathId = `badge-clip-${uniqueId}`;
  const glintGradientId = `glint-grad-${uniqueId}`;
  const badgeGradientId = `badge-grad-${uniqueId}`;

  // Accurate 12-point rounded star-burst path matching the uploaded image
  // Peaks sit at 15°, 45°, 75°... so the top & sides have a symmetric valley dip
  const badgePath =
    "M 14.43 2.92 C 13.71 2.73 12.70 4.00 12.00 4.00 C 11.30 4.00 10.29 2.73 9.57 2.92 C 8.85 3.11 8.69 4.73 8.00 5.07 C 7.31 5.42 5.79 4.74 5.21 5.21 C 4.64 5.69 5.32 7.21 5.07 8.00 C 4.83 8.79 3.11 8.85 2.92 9.57 C 2.73 10.29 4.00 11.30 4.00 12.00 C 4.00 12.70 2.73 13.71 2.92 14.43 C 3.11 15.15 4.73 15.31 5.07 16.00 C 5.42 16.69 4.74 18.21 5.21 18.79 C 5.69 19.36 7.21 18.68 8.00 18.93 C 8.79 19.17 8.85 20.89 9.57 21.08 C 10.29 21.27 11.30 20.00 12.00 20.00 C 12.70 20.00 13.71 21.27 14.43 21.08 C 15.15 20.89 15.31 19.27 16.00 18.93 C 16.69 18.58 18.21 19.26 18.79 18.79 C 19.36 18.31 18.68 16.79 18.93 16.00 C 19.17 15.21 20.89 15.15 21.08 14.43 C 21.27 13.71 20.00 12.70 20.00 12.00 C 20.00 11.30 21.27 10.29 21.08 9.57 C 20.89 8.85 19.27 8.69 18.93 8.00 C 18.58 7.31 19.26 5.79 18.79 5.21 C 18.31 4.64 16.79 5.32 16.00 5.07 C 15.21 4.83 15.15 3.11 14.43 2.92 Z";

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="Verified"
      role="img"
      {...props}
    >
      <defs>
        {/* Clip path to keep the glint strictly inside the badge boundaries */}
        <clipPath id={clipPathId}>
          <path d={badgePath} />
        </clipPath>

        {/* Subtle 3D surface lighting gradient for a premium look */}
        <linearGradient id={badgeGradientId} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#3B93FF" />
          <stop offset="50%" stopColor={badgeColor} />
          <stop offset="100%" stopColor="#0D5BD9" />
        </linearGradient>

        {/* Shimmer / Glint light beam gradient */}
        <linearGradient id={glintGradientId} x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0" />
          <stop offset="35%" stopColor="#FFFFFF" stopOpacity="0.12" />
          <stop offset="50%" stopColor="#FFFFFF" stopOpacity="0.6" />
          <stop offset="65%" stopColor="#FFFFFF" stopOpacity="0.12" />
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
        </linearGradient>
      </defs>

      {/* Main Badge Body */}
      <path d={badgePath} fill={`url(#${badgeGradientId})`} />

      {/* Subtle inner rim border for extra depth */}
      <path
        d={badgePath}
        stroke="#FFFFFF"
        strokeOpacity="0.2"
        strokeWidth="0.4"
        clipPath={`url(#${clipPathId})`}
      />

      {/* Animated Glint Effect inside the Badge */}
      {enableGlint && (
        <g clipPath={`url(#${clipPathId})`}>
          <rect
            x="-24"
            y="-12"
            width="14"
            height="48"
            fill={`url(#${glintGradientId})`}
            transform="rotate(25 12 12)"
          >
            <animate
              attributeName="x"
              values="-28; 36; 36"
              keyTimes="0; 0.35; 1"
              dur={glintDuration}
              repeatCount="indefinite"
            />
          </rect>
        </g>
      )}

      {/* Accurate thick rounded checkmark matching the reference image */}
      <path
        d="M 8.6 12.4 L 10.9 14.5 L 15.6 9.8"
        stroke={checkColor}
        strokeWidth="2.1"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
};

export default VerifiedBadge;

