            <span className="text-[#1D9BF0]">12-Point Scalloped</span>
          </div>
          <h2 className="text-2xl sm:text-3xl font-semibold tracking-tight text-white">
            Verified Badge Component
          </h2>
          <p className="text-sm text-neutral-400 max-w-md mx-auto">
            Accurate vector geometry with tactile top-rim micro bevel and seamless theme cutout checkmark.
          </p>
        </div>

        <div className="relative rounded-2xl bg-[#111318] border border-white/10 p-6 shadow-2xl overflow-hidden backdrop-blur-xl">
          <div className="absolute -top-24 -right-24 w-48 h-48 bg-[#1D9BF0]/15 rounded-full blur-3xl pointer-events-none" />

          <div className="flex items-start gap-4">
            <div className="relative w-14 h-14 rounded-full bg-gradient-to-tr from-neutral-800 to-neutral-700 border border-white/15 flex items-center justify-center text-lg font-bold text-white shadow-inner shrink-0">
              AS
