            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-1.5 flex-wrap">
                <span className="font-semibold text-white text-base tracking-tight truncate">
                  Abu Sayeed
                </span>
                <VerifiedBadge
                  size={activeSize}
                  badgeColor={currentPreset.badgeColor}
                  checkColor={currentPreset.checkColor}
                />
              </div>
              <p className="text-xs text-neutral-400 mt-0.5">@abushaidislam · Building cool web tools</p>
              <p className="text-sm text-neutral-300 mt-3 leading-relaxed">
                Full-stack developer & open-source enthusiast. Crafting minimalist dark-mode interfaces and developer utilities.
              </p>

              <div className="flex items-center gap-4 mt-4 text-xs text-neutral-400">
                <div><span className="font-semibold text-white">1,248</span> Following</div>
                <div><span className="font-semibold text-white">18.4K</span> Followers</div>
              </div>
            </div>
          </div>
        </div>

        <div className="rounded-xl bg-[#111318]/70 border border-white/5 p-5 flex flex-col gap-5">
          <div>
            <span className="text-xs font-medium text-neutral-400 uppercase tracking-wider block mb-2.5">
              Theme Presets
            </span>
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
              {COLOR_PRESETS.map((preset, idx) => (
                <button
                  key={preset.name}
                  onClick={() => setSelectedPreset(idx)}
                  className={cn("flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-medium transition-all text-left border",
                    selectedPreset === idx
                      ? "bg-white/10 border-white/20 text-white shadow-sm"
                      : "bg-white/[0.02] border-transparent text-neutral-400 hover:bg-white/[0.05] hover:text-neutral-200"
                  )}
