const BADGE_PATH =
  "M 14.43 2.92 C 13.71 2.73 12.70 4.00 12.00 4.00 C 11.30 4.00 10.29 2.73 9.57 2.92 C 8.85 3.11 8.69 4.73 8.00 5.07 C 7.31 5.42 5.79 4.74 5.21 5.21 C 4.64 5.69 5.32 7.21 5.07 8.00 C 4.83 8.79 3.11 8.85 2.92 9.57 C 2.73 10.29 4.00 11.30 4.00 12.00 C 4.00 12.70 2.73 13.71 2.92 14.43 C 3.11 15.15 4.73 15.31 5.07 16.00 C 5.42 16.69 4.74 18.21 5.21 18.79 C 5.69 19.36 7.21 18.68 8.00 18.93 C 8.79 19.17 8.85 20.89 9.57 21.08 C 10.29 21.27 11.30 20.00 12.00 20.00 C 12.70 20.00 13.71 21.27 14.43 21.08 C 15.15 20.89 15.31 19.27 16.00 18.93 C 16.69 18.58 18.21 19.26 18.79 18.79 C 19.36 18.31 18.68 16.79 18.93 16.00 C 19.17 15.21 20.89 15.15 21.08 14.43 C 21.27 13.71 20.00 12.70 20.00 12.00 C 20.00 11.30 21.27 10.29 21.08 9.57 C 20.89 8.85 19.27 8.69 18.93 8.00 C 18.58 7.31 19.26 5.79 18.79 5.21 C 18.31 4.64 16.79 5.32 16.00 5.07 C 15.21 4.83 15.15 3.11 14.43 2.92 Z";

export const VerifiedBadge: React.FC<VerifiedBadgeProps> = ({
  size = 32,
  tier = "pro",
  enableGlint = true,
  className = "",
  ...rest
}) => {
  const uid = useId();
  const config = VERIFIED_THEMES[tier];

  const ids = {
    clip: `clip-${uid}`,
    borderGrad: `border-${uid}`,
    vignetteGrad: `vignette-${uid}`,
    curveGrad: `curve-${uid}`,
    highlightGrad: `highlight-${uid}`,
    glintGrad: `glint-${uid}`,
    blurMd: `blur-md-${uid}`,
    blurSm: `blur-sm-${uid}`,
    checkShadow: `check-shadow-${uid}`,
  };

  return (
    <motion.svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      whileHover={{ scale: 1.06 }}
      whileTap={{ scale: 0.95 }}
      transition={{ type: "spring", stiffness: 400, damping: 22 }}
      className={`inline-block select-none overflow-visible drop-shadow-[0_4px_10px_rgba(0,0,0,0.5)] ${className}`}
      aria-label={`Verified ${tier} badge`}
      role="img"
      {...rest}
    >
      <defs>
        {/* 1. Scalloped Clip Path (Confines all glows strictly inside the 12-point shape) */}
        <clipPath id={ids.clip}>
          <path d={BADGE_PATH} />
        </clipPath>

        {/* 2. Outer 135deg Metallic Rim Gradient */}
        <linearGradient id={ids.borderGrad} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor={config.borderStops[0]} />
          <stop offset="50%" stopColor={config.borderStops[1]} />
          <stop offset="100%" stopColor={config.borderStops[2]} />
        </linearGradient>

        {/* 3. Inner Vignette Ambient Ring (Simulates inset box-shadow) */}
        <radialGradient id={ids.vignetteGrad} cx="50%" cy="50%" r="50%">
          <stop offset="55%" stopColor={config.vignetteColor} stopOpacity="0" />
          <stop offset="85%" stopColor={config.vignetteColor} stopOpacity="0.55" />
          <stop offset="100%" stopColor={config.vignetteColor} stopOpacity="0.95" />
        </radialGradient>

        {/* 4. Bottom Curved Glow Gradient */}
        <radialGradient id={ids.curveGrad} cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor={config.curveGlowStops[0]} stopOpacity="0.95" />
          <stop offset="50%" stopColor={config.curveGlowStops[1]} stopOpacity="0.65" />
          <stop offset="100%" stopColor={config.curveGlowStops[1]} stopOpacity="0" />
        </radialGradient>

        {/* 5. Extra Bottom Core Highlight */}
        <radialGradient id={ids.highlightGrad} cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor={config.highlightStops[0]} stopOpacity="1" />
          <stop offset="60%" stopColor={config.highlightStops[1]} stopOpacity="0.7" />
          <stop offset="100%" stopColor={config.highlightStops[1]} stopOpacity="0" />
        </radialGradient>

        {/* 6. Glint / Shimmer Light Beam */}
        <linearGradient id={ids.glintGrad} x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="#ffffff" stopOpacity="0" />
          <stop offset="40%" stopColor="#ffffff" stopOpacity="0.08" />
          <stop offset="50%" stopColor="#ffffff" stopOpacity="0.45" />
          <stop offset="60%" stopColor="#ffffff" stopOpacity="0.08" />
          <stop offset="100%" stopColor="#ffffff" stopOpacity="0" />
        </linearGradient>

        {/* SVG Blur Filters matching TierBadge's blur(4px) and blur(2px) */}
        <filter id={ids.blurMd} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="1.6" />
        </filter>
        <filter id={ids.blurSm} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="0.8" />
        </filter>

        {/* Subtle Checkmark Glow */}
        <filter id={ids.checkShadow} x="-30%" y="-30%" width="160%" height="160%">
          <feDropShadow dx="0" dy="0.5" stdDeviation="0.8" floodColor="#000000" floodOpacity="0.6" />
          <feDropShadow dx="0" dy="0" stdDeviation="1.2" floodColor={config.checkGlow} floodOpacity="0.45" />
        </filter>
      </defs>

      {/* --- ALL INNER LAYERS CLIPPED TO THE 12-POINT STAR --- */}
      <g clipPath={`url(#${ids.clip})`}>
        {/* Layer 1: Dark Base Background */}
        <path d={BADGE_PATH} fill={config.baseBg} />

        {/* Layer 2: Inner Vignette Ambient Effect */}
        <path d={BADGE_PATH} fill={`url(#${ids.vignetteGrad})`} />

        {/* Layer 3: Center Dark Mask (Keeps area behind checkmark clean & high-contrast) */}
        <circle
          cx="12"
          cy="11.5"
          r="5.8"
          fill={config.centerMaskBg}
          filter={`url(#${ids.blurSm})`}
          opacity="0.9"
        />

        {/* Layer 4: Bottom Curved Animated Glow (Curves upward from bottom edge) */}
        <motion.ellipse
          cx="12"
          cy="20"
          rx="7.5"
          ry="5"
          fill={`url(#${ids.curveGrad})`}
          filter={`url(#${ids.blurMd})`}
          initial={{ y: 6, scaleY: 0.3, opacity: 0 }}
          animate={{ y: 0, scaleY: 1, opacity: 1 }}
          transition={{ duration: 0.85, ease: [0.16, 1, 0.3, 1] }}
        />

        {/* Layer 5: Extra Bottom Inner Soft Highlight */}
        <motion.ellipse
          cx="12"
          cy="20.5"
          rx="4.8"
          ry="2.6"
          fill={`url(#${ids.highlightGrad})`}
          filter={`url(#${ids.blurSm})`}
          initial={{ y: 4, opacity: 0 }}
          animate={{ y: 0, opacity: 0.95 }}
          transition={{ duration: 0.9, delay: 0.1, ease: "easeOut" }}
        />

        {/* Layer 6: Periodic Glint Sweep */}
        {enableGlint && (
          <motion.rect
            x="-24"
            y="-12"
            width="12"
            height="48"
            fill={`url(#${ids.glintGrad})`}
            transform="rotate(25 12 12)"
            animate={{ x: [-26, 38, 38] }}
            transition={{
              duration: 3.6,
              times: [0, 0.35, 1],
              repeat: Infinity,
              ease: "easeInOut",
            }}
          />
        )}

        {/* Layer 7: Outer 1.5px Gradient Border Rim (Drawn inside clip for crisp edges) */}
        <path
          d={BADGE_PATH}
          stroke={`url(#${ids.borderGrad})`}
          strokeWidth="1.6"
          fill="none"
        />
      </g>

      {/* --- FOREGROUND CHECKMARK --- */}
      <motion.path
        d="M 8.6 12.4 L 10.9 14.5 L 15.6 9.8"
        stroke={config.checkColor}
        strokeWidth="2.1"
        strokeLinecap="round"
        strokeLinejoin="round"
        filter={`url(#${ids.checkShadow})`}
        initial={{ pathLength: 0, opacity: 0 }}
        animate={{ pathLength: 1, opacity: 1 }}
        transition={{ duration: 0.5, delay: 0.15, ease: "easeOut" }}
      />
    </motion.svg>
  );
};

export default VerifiedBadge;
